fn get_i_th_element_of_opt(opt: &Option, i: Int) -> Option {
    match opt {
        Some(x) => {
            if i == 0 {
                Some(x)
            } else {
                None
            }
        },
        None => {
            None
        },
    }
}

fn main() {
    let opt = Some(4)
    print(get_i_th_element_of_opt(&opt, 0))
    print(get_i_th_element_of_opt(&opt, 1))
    let none = None
    print(get_i_th_element_of_opt(&none, 0))
    drop none
}

enum Result {
    Ok(T),
    Err(E),
}

fn get_i_th_element_of_res(res: &Result, i: Int) -> Result {
    match res {
        Ok(x) => {
            if i == 0 {
                Ok(x)
            } else {
                Err("error")
            }
        },
        Err(e) => {
            Err(e)
        },
    }
}

fn main() {
    let opt = Ok(4)
    print(get_i_th_element_of_res(&opt, 0))
    print(get_i_th_element_of_res(&opt, 1))
    let none = Err("error")
    print(get_i_th_element_of_res(&none, 0))
    drop none
}

