fn words(s: Str) -> Int {
    let mut n = 0
    let mut i = 0
    while i < len(&s) {
        match get(&s, i) {
            Some(c) => if c == " " { i == i + 1 } else { n == n + 1 },
            None => breakn,
        }
    }
    n
}

